INSERT INTO produtos (id, nome, slug, descricao, descricao_curta, categoria_id, marca, preco_base, preco_promocional, ativo, destaque) VALUES
    ('22222222-2222-8888-8888-000000000001', 'T-Shirt Sorriso Maroto', 'camiseta-sorriso-maroto', 'A T-shirt que começou tudo na MM MODAS. Algodão penteado 100%, modelagem oversized e o sorriso do Menino Mau estampado no peito.', 'T-Shirt Sorriso Maroto', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 129.90, 99.90, TRUE, TRUE),
    ('22222222-2222-8888-8888-000000000002', 'T-Shirt Oversized Street MM', 'tshirt-oversized-street-mm', 'Modelagem boxy com ombro deslocado, gola canelada de 3cm e malha pesada 240g. O caimento urbano definitivo.', 'T-Shirt Oversized Street MM', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 139.90, 109.90, TRUE, TRUE),
    ('22222222-2222-8888-8888-000000000003', 'T-Shirt Heavy Cotton No Rules', 'tshirt-heavy-cotton-no-rules', 'Algodão encorpado que estrutura no corpo sem esquentar. Estampa em silk de alto relevo nas costas.', 'T-Shirt Heavy Cotton No Rules', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 114.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000004', 'T-Shirt Estonada Vintage Club', 'tshirt-estonada-vintage-club', 'Lavagem estonada exclusiva com toque aveludado e visual retrô. Cada peça tem nuances únicas na costura.', 'T-Shirt Estonada Vintage Club', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 149.90, 119.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000005', 'T-Shirt Boxy Noite Recife', 'tshirt-boxy-noite-recife', 'Inspirada na brisa noturna e nos rolês da cidade. Corte quadrado moderno e etiqueta bordada na barra.', 'T-Shirt Boxy Noite Recife', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 104.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000006', 'T-Shirt Graphic Caos Criativo', 'tshirt-graphic-caos-criativo', 'Ilustração autoral do estúdio MM nas costas e logo minimalista na frente. Malha fio 30.1 penteado.', 'T-Shirt Graphic Caos Criativo', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 94.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000007', 'T-Shirt Gola Alta Ribana', 'tshirt-gola-alta-ribana', 'Gola careca reforçada que nunca esgarça. Ideal para usar sozinha ou em sobreposição com jaqueta aberta.', 'T-Shirt Gola Alta Ribana', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 99.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000008', 'T-Shirt Oversized Arte Urbana', 'tshirt-oversized-arte-urbana', 'Traços de graffiti e tipografia bold estampados em toque zero. Liberdade de movimento o dia inteiro.', 'T-Shirt Oversized Arte Urbana', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 129.90, 109.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000009', 'T-Shirt Acid Wash Menino Mau', 'tshirt-acid-wash-menino-mau', 'Efeito marmorizado ácido com patch emborrachado no peito. Presença garantida em qualquer festival.', 'T-Shirt Acid Wash Menino Mau', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 124.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000010', 'T-Shirt Minimal Pocket MM', 'tshirt-minimal-pocket-mm', 'Bolso frontal com microbordado do mascote. Para quem curte discrição com detalhe maroto de perto.', 'T-Shirt Minimal Pocket MM', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 89.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000011', 'T-Shirt Drop Shoulder Horizonte', 'tshirt-drop-shoulder-horizonte', 'Mangas amplas até o cotovelo e caimento fluido em algodão sustentável certificado.', 'T-Shirt Drop Shoulder Horizonte', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 104.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000012', 'T-Shirt Manga Longa Street', 'tshirt-manga-longa-street', 'Punhos canelados firmes e estampa tipográfica nas mangas. Perfeita para meia-estação com bermuda ou cargo.', 'T-Shirt Manga Longa Street', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 144.90, 119.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000013', 'T-Shirt Suede Touch Premium', 'tshirt-suede-touch-premium', 'Malha peletizada com toque de camurça ultra macio. Elegância casual que dispensa esforço.', 'T-Shirt Suede Touch Premium', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 129.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000014', 'T-Shirt Listrada Retro 90s', 'tshirt-listrada-retro-90s', 'Listras horizontais tingidas no fio (não desbotam) e modelagem folgada inspirada no skate dos anos 90.', 'T-Shirt Listrada Retro 90s', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 109.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000015', 'T-Shirt Contrast Stitch MM', 'tshirt-contrast-stitch-mm', 'Costuras externas aparentes em linha contrastante e corte estruturado de alta gramatura.', 'T-Shirt Contrast Stitch MM', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 114.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000016', 'T-Shirt Raglan Urban Block', 'tshirt-raglan-urban-block', 'Mangas em cor contrastante com recorte esportivo clássico e gola contrastante.', 'T-Shirt Raglan Urban Block', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 114.90, 92.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000017', 'T-Shirt Slub Flamê Brisa', 'tshirt-slub-flame-brisa', 'Textura flamê levemente irregular que deixa a pele respirar nos dias mais quentes do ano.', 'T-Shirt Slub Flamê Brisa', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 86.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000018', 'T-Shirt Collector Edition MM', 'tshirt-collector-edition-mm', 'Edição numerada com bordado cheio no peito e acabamento perfumado de fábrica.', 'T-Shirt Collector Edition MM', (SELECT id FROM categorias WHERE slug = 'tshirts'), 'MM Modas', 134.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000019', 'Camiseta Sem Pedir Licença', 'camiseta-sem-pedir-licenca', 'Básica? Nunca. Malha fio 30.1, gola canelada e a frase que resume a MM MODAS nas costas. Combina com tudo.', 'Camiseta Sem Pedir Licença', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 99.90, 79.90, TRUE, TRUE),
    ('22222222-2222-8888-8888-000000000020', 'Regata Cachos ao Vento', 'regata-cachos-ao-vento', 'Cavas amplas, malha leve e caimento reto. Feita pro calor e pra quem gosta de curtir o sol sem aperto.', 'Regata Cachos ao Vento', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 69.90, NULL, TRUE, TRUE),
    ('22222222-2222-8888-8888-000000000021', 'Camiseta Básica Essencial MM', 'camiseta-basica-essencial-mm', 'O alicerce do guarda-roupa masculino. Algodão penteado macio que não dá bolinha e não torce na lavagem.', 'Camiseta Básica Essencial MM', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 69.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000022', 'Camiseta Henley 3 Botões', 'camiseta-henley-3-botoes', 'Gola portuguesa com três botões amadeirados. Valoriza o peitoral e substitui a camisa no encontro casual.', 'Camiseta Henley 3 Botões', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 119.90, 94.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000023', 'Regata Machão Praia & Asfalto', 'regata-machao-praia-asfalto', 'Ombros largos e corte reto que veste bem na orla ou no churrasco de domingo.', 'Regata Machão Praia & Asfalto', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 74.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000024', 'Camiseta Gola V Discreta', 'camiseta-gola-v-discreta', 'Decote V na medida certa — sem exageros — para alongar a silhueta com elegância.', 'Camiseta Gola V Discreta', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 74.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000025', 'Camiseta Manga Longa Térmica Casual', 'camiseta-manga-longa-casual', 'Meia-malha encorpada de manga comprida para noites amenas ou ambientes climatizados.', 'Camiseta Manga Longa Térmica Casual', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 99.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000026', 'Regata Canelada Old School', 'regata-canelada-old-school', 'Ribana de algodão com elastano que acompanha o contorno do corpo. Ótima sozinha ou sob camisa de botão aberta.', 'Regata Canelada Old School', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 79.90, 64.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000027', 'Camiseta Estampa Sorriso de Canto', 'camiseta-estampa-sorriso-canto', 'Estampa exclusiva em serigrafia à base d’água com toque zero e cores vibrantes.', 'Camiseta Estampa Sorriso de Canto', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 84.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000028', 'Camiseta Pima Touch Luxo', 'camiseta-pima-touch-luxo', 'Fibras longas de algodão com brilho sutil e frescor incomparável na pele.', 'Camiseta Pima Touch Luxo', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 119.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000029', 'Camiseta Barra Curva Longline', 'camiseta-barra-curva-longline', 'Comprimento levemente alongado e barra arredondada que traz modernidade imediata ao visual.', 'Camiseta Barra Curva Longline', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 89.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000030', 'Camiseta Henley Manga Longa', 'camiseta-henley-manga-longa', 'Malha waffles texturizada com botões frontais. Visual rústico e sofisticado ao mesmo tempo.', 'Camiseta Henley Manga Longa', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 129.90, 109.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000031', 'Regata Cavada Vibe Tropical', 'regata-cavada-vibe-tropical', 'Cores solares e tecido ultra fresco com secagem rápida para dias de piscina e praia.', 'Regata Cavada Vibe Tropical', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 69.90, NULL, TRUE, FALSE),
