    ('22222222-2222-8888-8888-000000000033', 'Camiseta Gola Careca Fio Egípcio', 'camiseta-fio-egipcio-mm', 'Toque gelado e maciez extrema. Não desbota mesmo após dezenas de lavagens.', 'Camiseta Gola Careca Fio Egípcio', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 149.90, 124.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000034', 'Camiseta Dupla Face Urbana', 'camiseta-dupla-face-urbana', 'Costura reversível que permite usar dos dois lados: um liso minimalista e outro estampado.', 'Camiseta Dupla Face Urbana', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 96.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000035', 'Regata Machão Estonada Rock', 'regata-machao-estonada-rock', 'Acabamento fio a fio nas cavas e lavagem chumbo. Atitude pura para shows e rolês.', 'Regata Machão Estonada Rock', (SELECT id FROM categorias WHERE slug = 'camisetas'), 'MM Modas', 79.90, NULL, TRUE, FALSE),
