    ('22222222-2222-8888-8888-000000000037', 'Polo Menino Bom (Só na Aparência)', 'polo-menino-bom', 'Piquet de algodão, gola firme e dois botões. Cara de bom moço pro almoço de família — o resto a gente não conta.', 'Polo Menino Bom (Só na Aparência)', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 169.90, 139.90, TRUE, TRUE),
