    ('22222222-2222-8888-8888-000000000039', 'Polo Gola Padre Minimal', 'polo-gola-padre-minimal', 'Sem pontas na gola para um visual contemporâneo e limpo. Vai do escritório ao barzinho sem esforço.', 'Polo Gola Padre Minimal', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 174.90, 144.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000040', 'Polo Tricô Texturizada', 'polo-trico-texturizada', 'Trama aberta em tricô leve de algodão. O ápice da elegância casual masculina.', 'Polo Tricô Texturizada', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 169.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000041', 'Polo Friso Duplo Sport', 'polo-friso-duplo-sport', 'Gola e punhos com listras duplas contrastantes que trazem uma pegada esportiva retrô.', 'Polo Friso Duplo Sport', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 134.90, NULL, TRUE, FALSE),
