    ('22222222-2222-8888-8888-000000000043', 'Polo Zíper Frontal Urban', 'polo-ziper-frontal-urban', 'Substitui os botões por um zíper metálico discreto. Moderna, arrojada e zero tradicional.', 'Polo Zíper Frontal Urban', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 179.90, 149.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000044', 'Polo Manga Longa Inverno', 'polo-manga-longa-inverno', 'Piquet encorpado de manga comprida com punho canelado. Perfeita para dias frescos com calça chino.', 'Polo Manga Longa Inverno', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 159.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000045', 'Polo Listrada Rugby Club', 'polo-listrada-rugby-club', 'Listras largas estilo rugby britânico e colarinho em sarja branca contrastante.', 'Polo Listrada Rugby Club', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 154.90, NULL, TRUE, FALSE),
