    ('22222222-2222-8888-8888-000000000050', 'Polo Colorblock 90s', 'polo-colorblock-90s', 'Recortes geométricos nas cores da marca para quem não passa despercebido.', 'Polo Colorblock 90s', (SELECT id FROM categorias WHERE slug = 'polos'), 'MM Modas', 142.90, NULL, TRUE, FALSE),
