    ('22222222-2222-8888-8888-000000000206', 'Cinto Couro Dupla Face Fivela', 'cinto-couro-dupla-face', 'Fivela giratória em metal escovado: de um lado preto clássico, do outro caramelo casual. Dois cintos em um.', 'Cinto Couro Dupla Face Fivela', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 119.90, 99.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000207', 'Relógio Analógico Minimal Noir', 'relogio-analogico-minimal-noir', 'Caixa de 40mm em aço fosco, mostrador limpo e pulseira intercambiável. Pontualidade com presença.', 'Relógio Analógico Minimal Noir', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 299.90, 249.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000208', 'Corrente Veneziana Aço Inox', 'corrente-veneziana-aco-inox', 'Aço cirúrgico 316L que não escurece no banho nem no mar. O brilho discreto que destaca qualquer camiseta.', 'Corrente Veneziana Aço Inox', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 89.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000209', 'Boné Five Panel Streetwear', 'bone-five-panel-streetwear', 'Aba reta flexível, copa rasa em cinco painéis e fecho de engate rápido.', 'Boné Five Panel Streetwear', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 84.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000210', 'Boné Trucker Telinha Brisa', 'bone-trucker-telinha-brisa', 'Frente estruturada com patch bordado e traseira em tela respirável para dias de sol forte.', 'Boné Trucker Telinha Brisa', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 79.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000211', 'Cinto Tático Lona Engate Rápido', 'cinto-tatico-lona-engate', 'Fita de nylon de alta resistência e fivela magnética sem furos — ajuste milimétrico na cintura.', 'Cinto Tático Lona Engate Rápido', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 74.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000212', 'Óculos Retrô Redondo Lente Fumê', 'oculos-retro-redondo-fume', 'Ponte dupla metálica e lentes com proteção UV400. Estilo intelectual maroto.', 'Óculos Retrô Redondo Lente Fumê', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 189.90, 159.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000213', 'Porta-Cartões Magnético RFID', 'porta-cartoes-magnetico-rfid', 'Bloqueio contra aproximação indevida e ejeção rápida de cartões com um clique.', 'Porta-Cartões Magnético RFID', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 59.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000214', 'Gorro Pescador Short Beanie', 'gorro-pescador-short-beanie', 'Modelagem curta acima da orelha estilo urbano europeu.', 'Gorro Pescador Short Beanie', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 64.90, NULL, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000215', 'Pulseira Couro Trançado & Aço', 'pulseira-couro-trancado-aco', 'Fecho magnético em aço escovado com gravação a laser MM. Combina perfeitamente ao lado do relógio.', 'Pulseira Couro Trançado & Aço', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 69.90, 54.90, TRUE, FALSE),
    ('22222222-2222-8888-8888-000000000216', 'Bag Transversal Impermeável Pro', 'bag-transversal-impermeavel-pro', 'Comporta tablet de até 10 polegadas, carteira, óculos e chaves com proteção total contra chuva.', 'Bag Transversal Impermeável Pro', (SELECT id FROM categorias WHERE slug = 'acessorios'), 'MM Modas', 139.90, NULL, TRUE, FALSE)
