-- Migracao V3: Atualiza catalogo do banco de dados de MM GAMES para MM MODAS
-- (12 categorias de moda masculina & acessorios e 216 produtos com variacoes e estoque)

-- 1. Desativa categorias e produtos legados de jogos
UPDATE categorias SET ativa = FALSE WHERE slug IN ('rpg', 'familia', 'estrategia', 'cartas', 'party');
UPDATE produtos SET ativo = FALSE WHERE slug IN (
    'jogo-da-velha', 'monopoli', 'xadrez-oficial', 'dnd-livro-do-jogador',
    'call-of-cthulhu', 'ordem-paranormal', 'tormenta20', 'war-estrategia'
);

-- 2. Garante cupom promocional MENINOMAU10 ativo
VALUES ('MENINOMAU10', 'PERCENTUAL', 10.00, 0.00, NULL, TRUE)
ON CONFLICT (codigo) DO UPDATE SET ativo = TRUE, valor = 10.00;

-- 3. Upsert em lote das 12 categorias da MM MODAS (as 8 primeiras sao as exibidas na Home)
ON CONFLICT (slug) DO UPDATE SET nome = EXCLUDED.nome, ordem = EXCLUDED.ordem, ativa = TRUE;

-- 4. Upsert em lote dos 216 produtos da MM MODAS
ON CONFLICT (slug) DO UPDATE SET
    nome = EXCLUDED.nome,
    descricao = EXCLUDED.descricao,
    descricao_curta = EXCLUDED.descricao_curta,
    categoria_id = EXCLUDED.categoria_id,
    marca = EXCLUDED.marca,
    preco_base = EXCLUDED.preco_base,
    preco_promocional = EXCLUDED.preco_promocional,
    ativo = TRUE,
    destaque = EXCLUDED.destaque;

-- 5. Imagens principais
ON CONFLICT DO NOTHING;

-- 6. Variacoes em lote
ON CONFLICT (sku) DO NOTHING;

-- 7. Estoque inicial em lote
ON CONFLICT (variacao_id) DO NOTHING;
